// 自动注册
registerAppTranslations();

/**
 * 获取节点类型的翻译显示名称
 * 使用示例: getNodeDisplayName('aiImage') => 'AI图片' / 'AI Image'
 */
export function getNodeDisplayName(nodeType: string): string {
  const key = `nodes.${nodeType}`;
  const translated = i18n.t(key);
  // 如果翻译等于key本身，说明没有找到翻译，返回原始nodeType
  return translated === key ? nodeType : translated;
}

/**
 * 获取节点分类的翻译显示名称
 */
export function getCategoryDisplayName(category: string): string {
  const key = `nodes.category_${category}`;
  const translated = i18n.t(key);
  return translated === key ? category : translated;
}

/**
 * 获取通用的翻译文本
 * React组件中优先使用 i18n.t() 或 useLanguageStore
 * 此函数用于非React上下文
 */
export function translateText(key: string, fallback?: string): string {
  const translated = i18n.t(key);
  return translated === key ? (fallback || key) : translated;
}
